parameters.jsCode:
const ctx = $('Split Designs').first().json;
const raw = $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const match = raw.match(/\{[\s\S]*\}/);
let seo = {};
try { seo = JSON.parse(match?.[0] || '{}'); } catch (_) {}

return [{
  json: {
    ...ctx,
    seo,
    etsyTitle:         seo.etsyTitle         || '',
    etsyDescription:   seo.etsyDescription   || '',
    etsyTags:          seo.etsyTags          || [],
    amazonTitle:       seo.amazonTitle       || '',
    amazonBulletPoints:seo.amazonBulletPoints|| [],
    amazonKeywords:    seo.amazonKeywords    || '',
    seoFileName:       seo.fileName         || '',
    altText:           seo.altText          || ''
  }
}];
